package com.profa.messaging;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/messaging")public class MessagingController{final ConversationRepository c;final MessageRepository m;public MessagingController(ConversationRepository c,MessageRepository m){this.c=c;this.m=m;}@GetMapping("/conversations")public List<Conversation> conversations(){return c.findAll();}@PostMapping("/conversations")public Conversation conversation(Authentication a,@RequestBody Conversation x){x.setUserA(UUID.fromString(a.getName()));return c.save(x);}@GetMapping("/conversations/{id}/messages")public List<Message> messages(@PathVariable UUID id){return m.findAll().stream().filter(x->id.equals(x.getConversationId())).toList();}@PostMapping("/messages")public Message message(Authentication a,@RequestBody Message x){x.setSenderId(UUID.fromString(a.getName()));return m.save(x);}}